\begin{center}
\textbf{Having described fibre bundles, we ask if vector bundles are familiar objects in disguise.}
\end{center}

\begin{theorem}
    Let $\mathcal{P}_{GL_n(\mathbb{K})}(B)$ denote the set of isomorphism classes of principal $GL_n(\mathbb{K})$-bundles over $B$. The following is a bijective correspondence:
    $$\mathcal{P}_{GL_n(\mathbb{K})}(B) \longleftrightarrow \text{Vect}_{\mathbb{K}}^n(B)$$
\end{theorem}

\begin{corollary}
    If $f:A\rightarrow B$ is a homotopy equivalence, then, $f^*: \text{Vect}^n(B)\rightarrow \text{Vect}^n(A)$ is a bijection. ((i.e.) vector bundles are homotopy invariant).
\end{corollary}
\begin{proof}
    Let $g:B\rightarrow A$ be such that $f\circ g \sim \text{id}_B$ and $g\circ f\sim \text{id}_A$, then $g^*$ is the required inverse for $f^*$, as $f^*g^* \cong \text{id}^*_A$ and $g^*f^* \cong \text{id}^*_B$
\end{proof}

\begin{remark}
A more general result is true: Given a group $G$, let $\mathcal{P}_G(X)$ denote the set of all principal $G$-bundles, where $X$ is compact Hausdorff, then there exists a $G$-bundle $EG\rightarrow BG$, with a contractible total space, such that the following is a bijective correspondence:
$$[X, BG] \longleftrightarrow \mathcal{P}_G(X)$$
$EG$ is called the \textbf{universal bundle} and $BG$ the \textbf{classifying space} for the structure group $G$. This generalizes the theorem above for $G= GL_n{(\mathbb{K})}$, because of the correspondence between $GL_n{(\mathbb{K})}$-bundles and vector bundles of dimension $n$ established before, and the fact that $BGL_n{(\mathbb{K})} \simeq \text{Gr}(n, \mathbb{K}^{\infty})$, with $V(n, \mathbb{K}^{\infty}) \simeq \{*\}$ as the total space of the corresponding universal $O_{\mathbb K}(n)$-bundle.
\end{remark}

\begin{center}

$\text{Vect}_{\mathbb{K}}^n(B)$ encodes homotopy-theoretic information about $B$ in linear terms.

\end{center}

