Consequently, an ideal cannot be covered by finitely many prime ideals unless it is contained in one of them, as depicted here.
\begin{figure}[H]\centering
\includegraphics[width=.48\textwidth]{ca1-fig-04.pdf}
\end{figure}
\setcounter{theorem}{1}\begin{lemma}[Factoring]
If $\{\aa_i\}_{i=1}^n$ are ideals and $\pp$ is a prime ideal such that $\pp\supseteq\bigcap_{i=1}^n\aa_i$, then $\pp\supseteq\aa_i$ for some $i$.
\end{lemma}
\begin{proof}
If $\aa_i\nsubseteq\pp$ for every $i$, choose $x_i\in\aa_i$ with $x_i\notin\pp$. But $\prod_{i=1}^n x_i\in\bigcap_i\aa_i\subseteq\pp$, a contradiction.
\end{proof}
\begin{remark}
In particular, if $\pp=\bigcap_{i=1}^n\aa_i$, then $\pp=\aa_i$ for some $i$. If the $\aa_i$ are pairwise coprime and $\pp=\prod_{i=1}^n\aa_i$, then $\prod_i\aa_i=\bigcap_i\aa_i$, and again $\pp=\aa_i$ for some $i$.
\end{remark}
\setcounter{theorem}{2}\begin{proposition}
\[\rad((0))=\bigcap_{\pp\text{ prime}}\pp.\]
\end{proposition}
\begin{proof}
If $f\in\rad((0))$, then $f^n=0\in\pp$, so $f\in\pp$ and hence $f\in\bigcap_{\pp\text{ prime}}\pp$.
If $f\notin\rad((0))$, let $\Sigma$ be the poset of all ideals $\aa$ such that $f^n\notin\aa$ for every $n$. As $0\in\Sigma$, this poset is nonempty. If $\{\aa_i\}_{i\in I}$ is a chain, then $\bigcup_i\aa_i\in\Sigma$ and bounds the chain. By Zorn's lemma, $\Sigma$ has a maximal element $\mm$.
\emph{Claim:} $\mm$ is prime.
% Source page 10
Let $x,y\notin\mm$. Then $\mm+(x),\mm+(y)\notin\Sigma$ by maximality. Therefore, $f^a\in\mm+(x)$ and $f^b\in\mm+(y)$, so $f^{a+b}\in\mm+(xy)$ and thus $xy\notin\mm$. Therefore $f\notin\mm$, implying $f\notin\bigcap_{\pp\text{ prime}}\pp$.
\end{proof}
The following picture summarizes these relationships.
\begin{figure}[H]\centering
\includegraphics[width=.86\textwidth]{ca1-fig-05.pdf}
\end{figure}

\subsection{Modules}
\setcounter{definition}{3}\begin{definition}
$M$ is an \emph{$A$-module} if $M\in\Ob(\mathsf{AbGps})$ is equipped with a unital ring homomorphism $A\to\End_{\Ab}(M)$. If $M'<M$ is an additive subgroup stable under this action, then $M'$ is an \emph{$A$-submodule} of $M$.
\end{definition}
% Source page 11

\subsection{Tensor products}
If $M,N$ are $A$-modules, there is a universal object among all $A$-bilinear maps from $M\times N$ to $P$, denoted $M\otimes N$. Thus $f:M\times N\to P$ factors through an $A$-linear map $\widetilde f$, as shown.
\begin{figure}[H]\centering
\includegraphics[width=.48\textwidth]{ca1-fig-06.pdf}
\end{figure}
\paragraph{Construction.}
Consider the direct sum $\bigoplus_{i\in M\times N}A$. Let $C$ be the submodule generated by
\[
\begin{gathered}
(x+x',y)-(x,y)-(x',y),\qquad (x,y+y')-(x,y)-(x,y'),\\
(ax,y)-a(x,y),\qquad(x,ay)-a(x,y).
\end{gathered}
\]
Then $M\otimes N:=\bigl(\bigoplus_{i\in M\times N}A\bigr)/C$.
% The quotient is handwritten above the tensor-product paragraph; the later repeated definition is blank.

\subsection{Primary decomposition}
\setcounter{definition}{8}\begin{definition}
An ideal $\qq<A$ is \emph{primary} if
\[
xy\in\qq\text{ and }x\notin\qq\ \Longrightarrow\ y^n\in\qq\text{ for some }n\geq1.
\]
Equivalently, $xy\in\qq$ implies $x\in\qq$ or $y\in\rad(\qq)$, and every zero-divisor in $A/\qq$ is nilpotent. If $\rad(\qq)=\pp$, then $\qq$ is \emph{$\pp$-primary}.
\end{definition}
\begin{claim}
$\rad(\qq)$ is the smallest prime ideal containing $\qq$.
\end{claim}
\begin{proof}
% Source page 6
If $xy\in\rad(\qq)$, then $x^ny^n\in\qq$ for some $n>0$. Hence $x^n\in\qq$ or $(y^n)^m\in\qq$ for some $m>0$; thus $x$ or $y$ belongs to $\rad(\qq)$. Plainly $\qq\subseteq\rad(\qq)$, and every prime ideal containing $\qq$ also contains $\rad(\qq)$.
\end{proof}
\setcounter{example}{6}\begin{example}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item In $A=\Z$, $(0)$ and $(p^n)$ are primary ideals.
\setcounter{enumi}{1}\item In $A=\kk[x,y]$, let $\qq=(x,y^2)$. Then $A/\qq\cong\kk[y]/(y^2)$, whose zero-divisors are multiples of $y$. Hence $\qq$ is primary. Moreover, $\rad(\qq)=(x,y)=\pp$ is prime, and $\pp^2\subset\qq\subset\pp$. Thus not all primary ideals are powers of prime ideals.
\setcounter{enumi}{2}\item If $\rad(\aa)$ is maximal, then $\aa$ is primary. In particular, $\mm^n$ is $\mm$-primary. Here $A/\aa$ has only one prime ideal: $\rad(\aa)=\mm$ implies that $A/\aa\setminus\mm$ consists of units.
\end{enumerate}
\end{example}
\begin{remark}
In $\Z$, unique factorization gives $m=p_1^{a_1}\cdots p_r^{a_r}$, where $m\in\Z$ and the $p_i$ are primes. Equivalently,
\[(m)=\prod_{i=1}^r(p_i)^{a_i}=\bigcap_{i=1}^r(p_i)^{a_i}.\]
An appropriate generalization of this phenomenon to arbitrary rings requires replacing powers of primes by primary ideals. For certain rings, every ideal has an ``almost'' unique primary decomposition, $\aa=\bigcap_{i=1}^n\qq_i$, where $\qq_i$ is $\pp_i$-primary.
\end{remark}
% Source page 7

\setcounter{definition}{9}\begin{definition}
For an ideal $\aa<A$, an expression
\[\aa=\bigcap_{i=1}^n\qq_i,\qquad\qq_i\text{ is }\pp_i\text{-primary},\tag{*}\]
is a \emph{primary decomposition} of $\aa$. The set $\{\pp_i\}_{i=1}^n$ is the set of \emph{primes associated to $\aa$}.
\end{definition}
\begin{remark}
If $\qq_j\supseteq\bigcap_{k=1}^{\ell}\qq_{i_k}$, then $\qq_j$ is redundant in (*). Henceforth we assume our primary decomposition is \emph{irredundant}, or minimal.
\end{remark}
\setcounter{theorem}{8}\begin{lemma}
If $\qq_1,\ldots,\qq_n$ are $\pp$-primary, then so is $\bigcap_{i=1}^n\qq_i$.
\end{lemma}
\begin{proof}
Let $\qq:=\bigcap_{i=1}^n\qq_i$. We have $\rad(\qq)=\rad(\bigcap_{i=1}^n\qq_i)=\bigcap_{i=1}^n\rad(\qq_i)$.
% Source page 8
If $xy\in\qq$ and $x\notin\qq$, then there exists $i$ with $xy\in\qq_i$ and $x\notin\qq_i$, so $y\in\pp$.
\end{proof}
\paragraph{Consequence.}
If $\aa=\bigcap_{i=1}^n\qq_i$ is a primary decomposition, we can assume that the primes $\pp_i$ for which $\qq_i$ is $\pp_i$-primary are all distinct.
\setcounter{theorem}{9}\begin{lemma}
Let $\qq$ be $\pp$-primary and $x\in A$.
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item If $x\in\qq$, then $(\qq:x)=A$.
\setcounter{enumi}{1}\item If $x\notin\qq$, then $(\qq:x)$ is $\pp$-primary, and consequently $\rad((\qq:x))=\pp$.
\end{enumerate}
\end{lemma}
\begin{proof}
(i) is clear. For (ii), $y\in(\qq:x)\Rightarrow xy\in\qq$. As $x\notin\qq$, we get $y\in\pp$. Thus
\[
\qq\subseteq(\qq:x)\subseteq\pp
\ \Longrightarrow\ \rad(\qq)\subseteq\rad((\qq:x))\subseteq\rad(\pp)
\ \Longrightarrow\ \rad((\qq:x))=\pp.
\]
If $yz\in(\qq:x)$ and $y\notin\pp$, then $xyz\in\qq$, so $xz\in\qq$ and hence $z\in(\qq:x)$.
\end{proof}
% Source page 9

\setcounter{theorem}{10}\begin{theorem}[First uniqueness theorem]
The associated primes in an irredundant primary decomposition depend only on $\aa$.
\end{theorem}
\begin{proof}
Note that
\[\rad((\aa:x))=\bigcap_i\rad((\qq_i:x))=\bigcap_{x\notin\qq_i}\pp_i.\]
If $\rad((\aa:x))$ is prime, then it equals $\pp_j$ for some $j$. Since the decomposition is irredundant, for every $1\le i\le n$ there exists $x_i\notin\qq_i$ with $x_i\in\bigcap_{j\ne i}\qq_j$. This yields $\rad((\aa:x_i))=\pp_i$. Therefore the $\pp_i$ are precisely the primes of the form $\rad((\aa:x))$, and hence depend on $\aa$.
\end{proof}
% Source page 10

\setcounter{theorem}{11}\begin{lemma}
Let $S$ be a multiplicatively closed subset of $A$ and $\qq$ a $\pp$-primary ideal.
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item If $S\cap\pp\ne\varnothing$, then $S^{-1}\qq=S^{-1}A$.
\setcounter{enumi}{1}\item If $S\cap\pp=\varnothing$, then $S^{-1}\pp$-primary ideals of $S^{-1}A$ correspond to $\pp$-primary ideals of $A$.
\end{enumerate}
\end{lemma}
\begin{proof}
(i) If $s\in S\cap\pp$, then $s^n\in S\cap\qq$ for some $n>0$, so $S^{-1}\qq$ contains a unit.

(ii) If $\qq$ is $\pp$-primary, then $S^{-1}\qq$ is $S^{-1}\pp$-primary:
\[
\begin{aligned}
\frac xs\frac yt\in S^{-1}\qq
&\ \Longrightarrow\ uxy\in\qq\text{ for some }u\in S\subseteq A\setminus\pp
\ \Longrightarrow\ xy\in\qq\\
&\ \Longrightarrow\ x\in\qq\text{ or }y^n\in\qq
\ \Longrightarrow\ \frac xs\in S^{-1}\qq\text{ or }\left(\frac yt\right)^n\in S^{-1}\qq.
\end{aligned}
\]
Also, $\rad(S^{-1}\qq)=S^{-1}\rad(\qq)=S^{-1}\pp$. Conversely, the contraction of an $S^{-1}\pp$-primary ideal is $\pp$-primary.
\end{proof}
% Source page 11

\subsection{Isolated and embedded primes}
\paragraph{Second uniqueness theorem.}
Let $\Sigma$ be a set of prime ideals associated with $\aa$. Call $\Sigma$ \emph{isolated} if $\pp'\subseteq\pp\in\Sigma\Rightarrow\pp'\in\Sigma$. Set
\[S=A\setminus\bigcup_{\pp\in\Sigma}\pp.\]
Clearly $S$ is multiplicatively closed. Further, $\pp'\in\Sigma\Rightarrow\pp'\cap S=\varnothing$, while $\pp'\notin\Sigma\Rightarrow\pp'\nsubseteq\bigcup_{\pp\in\Sigma}\pp$ by prime avoidance, since $\pp'\nsubseteq\pp$ for every $\pp\in\Sigma$. Thus $\pp'\cap S\ne\varnothing$.

\subsection{Noetherian modules}
\setcounter{definition}{10}\begin{definition}
A module $M$ is \emph{Noetherian} (respectively, \emph{Artinian}) if every ascending (respectively, descending) chain of submodules is eventually constant. A ring $A$, viewed as a module over itself, is Noetherian (Artinian) if every ascending (descending) chain of ideals is eventually constant.
\end{definition}
\setcounter{definition}{11}\begin{definition}
For a ring $R$, let
\[d:=\sup\{n\mid\pp_0\subsetneq\pp_1\subsetneq\cdots\subsetneq\pp_n,\ \pp_i\text{ prime in }R\}.\]
Then $d$ is the \emph{dimension} of $R$, written $\dim(R)=d$.
\end{definition}
\paragraph{Comment.}
We shall focus on Noetherian rings, for Artinian rings will turn out to be Noetherian of dimension zero.
\setcounter{example}{7}\begin{example}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item $\Z/n\Z$, as a $\Z$-module, is Artinian and Noetherian.
\setcounter{enumi}{1}\item $\kk[x]$, being a PID, is Noetherian, but $(x)\supset(x^2)\supset(x^3)\supset\cdots$ forces it not to be Artinian.
\setcounter{enumi}{2}\item $\kk[x_1,x_2,\ldots]$ is neither Noetherian nor Artinian.
\setcounter{enumi}{3}\item If $R\hookrightarrow K$, where $K$ is the field of fractions of $R$, then $K$ is both Artinian and Noetherian, but $R$ can be neither, as in (iii), which is merely a domain.
\end{enumerate}
\end{example}
\setcounter{theorem}{12}\begin{proposition}
$M$ is Noetherian if and only if every submodule of $M$ is finitely generated.
\end{proposition}
\begin{proof}
Suppose $M$ is Noetherian and $N$ is a submodule of $M$. Set
\[\Sigma=\{N_0\subseteq N\mid N_0\text{ is a finitely generated submodule}\}.\]
Since $0\in\Sigma$, this set is nonempty. For every chain in $\Sigma$, its union is a submodule of $M$ and is finitely generated.
% Source page 2
Its finitely many generators all lie in one member of the chain, so the union equals that member and belongs to $\Sigma$. Zorn's lemma gives a maximal $N_0\in\Sigma$. If $N_0\ne N$, choose $x\in N\setminus N_0$; then $N_0\subset N_0+(x)$, absurd.

Conversely, let $M_1\subseteq M_2\subseteq\cdots$ be a chain of submodules. Then $\bigcup_{i=1}^{\infty}M_i$ is a submodule of $M$, hence is finitely generated, say by $x_1,\ldots,x_n$. If $x_i\in M_{n_i}$, then for $n=\max_i\{n_i\}$ one has $M_n=\bigcup_{i=1}^{\infty}M_i$.
\end{proof}
\setcounter{theorem}{13}\begin{proposition}
If $0\to M'\to M\xrightarrow{\beta}M''\to0$ is exact, then $M$ is Noetherian if and only if $M'$ and $M''$ are Noetherian.
\end{proposition}
\begin{proof}
If $M$ is Noetherian, every chain in $M'$ is a chain in $M$, and a chain in $M''$ corresponds to a chain in $M$ containing $M'$.

Conversely, let $L$ be a submodule of $M$. Let $\{x_i\}_{i=1}^n$ generate $\beta(L)$ and $\{y_j\}_{j=1}^m$ generate $L\cap M'$. For $x\in L$, write
\[\beta(x)=\sum_{i=1}^n r_i x_i\qquad(r_i\in A,\ x_i\in M'').\]
Since $M/M'\cong M''$, write $x_i=[\widetilde x_i]$, with $\widetilde x_i\in L$, and $\beta(x)=[x]$. Then
\[
x\equiv\sum_{i=1}^n r_i\widetilde x_i\pmod{M'},\qquad
x-\sum_{i=1}^n r_i\widetilde x_i\in L\cap M'.
\]
Thus $x-\sum_{i=1}^n r_i\widetilde x_i=\sum_{j=1}^m s_jy_j$, so
\[x=\sum_{i=1}^n r_i\widetilde x_i+\sum_{j=1}^m s_jy_j\qquad(x\in L).\]
Therefore $\{\widetilde x_i\}_{i=1}^n\cup\{y_j\}_{j=1}^m$ generates $L$, and $M$ is Noetherian.
\end{proof}
\setcounter{theorem}{14}\begin{corollary}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item If $M_1,\ldots,M_n$ are Noetherian, then $\bigoplus_{i=1}^n M_i$ is Noetherian.
\setcounter{enumi}{1}\item If $M$ is finitely generated over Noetherian $A$, then $M\cong A^n/P$ is Noetherian.
\setcounter{enumi}{2}\item If $\aa<A$ is an ideal of a Noetherian ring, then $A/\aa$ is Noetherian.
% Source page 3
\setcounter{enumi}{3}\item If $\varphi:A\twoheadrightarrow B$ and $A$ is Noetherian, then $B\cong A/\ker\varphi$ is Noetherian.
\setcounter{enumi}{4}\item If $A$ is Noetherian, then $S^{-1}A$ is Noetherian. In particular, for prime $\pp$, $A_{\pp}$ is Noetherian.
\end{enumerate}
\end{corollary}
\setcounter{theorem}{15}\begin{theorem}[Hilbert's basis theorem]
If $A$ is Noetherian, then $A[x]$ is Noetherian.
\end{theorem}
\begin{proof}
Let $\aa<A[x]$ be an ideal. Construct $I=(\text{leading coefficients of elements in }\aa)$. Since $I<A$, it is finitely generated, say by $\{a_i\}_{i=1}^n$. For every $1\le i\le n$, there exists $f_i\in\aa$ with $f_i=a_ix^{r_i}+\text{lower terms}$. Set $r=\max_{1\le i\le n}\{r_i\}$, and let $\aa':=(f_1,\ldots,f_n)\subset\aa$.

Let $f=ax^m+\text{lower terms}\in\aa$. Then $a\in I$, so $a=\sum_{i=1}^n u_ia_i$. If $m\ge r$, then $f-\sum_{i=1}^n u_if_ix^{m-r_i}\in\aa$ has degree less than $m$. Proceeding in this way gives $f=g+h$, with $\deg g<r$ and $h\in\aa'$.

Let $M$ be the $A$-submodule of $A[x]$ generated by $1,x,\ldots,x^{r-1}$. Then $\aa=(\aa\cap M)+\aa'$. Since $A$ is Noetherian, the finitely generated module $M$ is Noetherian, hence $\aa\cap M$ is finitely generated. If $\{g_i\}_{i=1}^k$ generates $\aa\cap M$, then $\{f_i\}_{i=1}^n\cup\{g_i\}_{i=1}^k$ generates $\aa$.
\end{proof}
\setcounter{theorem}{16}\begin{corollary}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item If $A$ is Noetherian, then $A[x_1,\ldots,x_n]$ is Noetherian.
% Source page 4
\setcounter{enumi}{1}\item A finitely generated algebra over Noetherian $A$ is Noetherian.
\end{enumerate}
\end{corollary}
\subsection{Noether's work on primary decomposition}
\setcounter{definition}{12}\begin{definition}
An ideal $\aa<A$ is \emph{irreducible} if $\aa=\bb\cap\mathfrak c\Rightarrow\aa=\bb$ or $\aa=\mathfrak c$.
\end{definition}
\setcounter{theorem}{17}\begin{proposition}
Every irreducible ideal in a Noetherian ring is primary.
\end{proposition}
\begin{proof}
Let $\aa<A$ be irreducible. Then $\aa$ is primary if and only if $(0)$ is primary in the Noetherian ring $A/\aa$. Let $xy=0$, $y\ne0$. Consider $\Ann(x)\subseteq\Ann(x^2)\subseteq\cdots$. There exists $n$ such that $\Ann(x^n)=\Ann(x^{n+1})=\cdots$.

\emph{Claim:} $(x^n)\cap(y)=(0)$. If $a\in(y)$, then $ax=0$; and if $a\in(x^n)$, then $a=bx^n$, so $bx^{n+1}=0$. Hence $b\in\Ann(x^{n+1})=\Ann(x^n)$, giving $a=0$.

Since $\aa$ is irreducible, so is $(0)$ in $A/\aa$. As $y\ne0$, we get $x^n=0$. Thus $(0)$ is primary in $A/\aa$.
\end{proof}
\setcounter{theorem}{18}\begin{theorem}
Every ideal in a Noetherian ring admits primary decomposition.
\end{theorem}
\begin{proof}
Set $\Sigma=\{\aa<A\mid\aa\text{ is not a finite intersection of irreducible ideals}\}$. If $\Sigma\ne\varnothing$, then, as every chain in $A$ stabilizes, $\Sigma$ satisfies the hypotheses of Zorn's
% Source page 5
lemma, which yields a maximal element $\aa$. This ideal is reducible, so $\aa=\bb\cap\mathfrak c$ with $\aa\subset\bb$ and $\aa\subset\mathfrak c$. By maximality, $\bb,\mathfrak c\notin\Sigma$; they are finite intersections of irreducible ideals, and hence so is $\aa$. This is absurd. Therefore $\Sigma=\varnothing$.
\end{proof}
\subsection{Artinian rings}
In the following chain of propositions we sketch why Artinian rings are a special kind of Noetherian ring, thereby justifying our focus on Noetherian modules.
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item In an Artinian ring every prime is maximal. If $\pp$ is prime, then $A/\pp$ is an Artinian integral domain. For $0\ne x\in A/\pp$, there is some $n$ with $(x^n)=(x^{n+1})$. Thus $x^n=x^{n+1}y$. Since $A/\pp$ is a domain, $x^n\ne0$ and $xy=1$. Hence $A/\pp$ is a field and $\pp$ is maximal.
\setcounter{enumi}{1}\item An Artinian ring has only finitely many maximal ideals. Define
\[\Sigma=\left\{\bigcap_{i=1}^n\mm_i\ \middle|\ n\in\N,\ \mm_i\text{ maximal}\right\}.\]
Since $A$ is Artinian, every chain in $\Sigma$ has a lower bound. By Zorn's lemma, there exists a minimal $\bigcap_{i=1}^{n_0}\mm_i\in\Sigma$. For any maximal ideal $\mm$, minimality yields $\mm\cap(\bigcap_i\mm_i)=\bigcap_i\mm_i$.
% Source page 6
Thus $\bigcap_i\mm_i\subseteq\mm$, so $\mm_i=\mm$ for some $i$.
\setcounter{enumi}{2}\item The nilradical of an Artinian ring is nilpotent.
\end{enumerate}
\setcounter{theorem}{19}\begin{theorem}
If $A$ is Artinian, then $A$ is Noetherian and $\dim(A)=0$.
\end{theorem}
\begin{proof}[Sketch]
If $A$ is Artinian, then $\dim(A)=0$. Let $\{\mm_i\}_{i=1}^n$ be the maximal ideals of $A$. For some $k$,
\[
\prod_{i=1}^n\mm_i^k\subseteq\left(\bigcap_{i=1}^n\mm_i\right)^k
=\bigl(\rad((0))\bigr)^k=0.
\]
\emph{Fact:} If $\prod_{i=1}^n\mm_i=0$, with the $\mm_i$ maximal and not necessarily distinct, then $A$ is Noetherian.

Indeed, $A$ is Noetherian if and only if $\mm_1$ and $A/\mm_1$ are Noetherian. The latter is a field, hence Noetherian, so $A$ is Noetherian if and only if $\mm_1$ is Noetherian. Further, $\mm_1$ is Noetherian if and only if $\mm_1\mm_2$ and $\mm_1/\mm_1\mm_2$ are Noetherian. Since $\mm_2(\mm_1/\mm_1\mm_2)=0$, the quotient is an $A/\mm_2$-vector space. The module $\mm_1$ is Artinian because $A$ is Artinian; hence $\mm_1/\mm_1\mm_2$ is an Artinian $A/\mm_2$-module, thus a finite-dimensional vector space. It is therefore a Noetherian $A/\mm_2$-module, and consequently a Noetherian $A$-module. Thus $\mm_1$ is Noetherian if and only if $\mm_1\mm_2$ is Noetherian.

Proceeding inductively to $\mm_1\mm_2\cdots\mm_n=0$ yields the fact that $A$ is Noetherian.
\end{proof}
% Source page 7

\begin{remark}
The converse is also true.
\end{remark}

Thus $s\mid r^n$, a contradiction, since we may choose $\gcd(r,s)=1$. Hence $y\in\Q$ is integral if and only if some monic $f\in\Z[x]$ satisfies $f(y)=0$. We generalize this concept to arbitrary rings.
\setcounter{definition}{13}\begin{definition}
Let $A$ be a subring of $B$. An element $y\in B$ is \emph{integral over $A$} if there exists a monic $f\in A[x]$ such that $f(y)=0$ in $B$. If every $y\in B$ is integral over $A$, we say $B$ is \emph{integral over $A$}. We say $A$ is \emph{integrally closed in $B$} if every element of $B$ integral over $A$ already lies in $A$. If $A$ is a domain, we say $A$ is \emph{integrally closed} if it is integrally closed in its field of fractions $K$.
\end{definition}
\setcounter{theorem}{20}\begin{proposition}
For rings $A,B$ as above, the following are equivalent:
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item $x\in B$ is integral over $A$.
\setcounter{enumi}{1}\item $A[x]$ is a finitely generated $A$-module.
\setcounter{enumi}{2}\item $A[x]$ is contained in a subring $C$ of $B$ that is a finitely generated $A$-module.
\end{enumerate}
This is essentially a consequence of Cayley--Hamilton.
\end{proposition}
\begin{proof}
(i)$\Rightarrow$(ii): There exist $a_i\in A$ with $x^n+a_1x^{n-1}+\cdots+a_n=0$. Thus $1,x,\ldots,x^{n-1}$ generate $A[x]$, since $x^{n+r}=-(a_1x^{n+r-1}+\cdots+a_nx^r)$.

(ii)$\Rightarrow$(iii): Set $C=A[x]$.

(iii)$\Rightarrow$(i): Let $\varphi\in\End_{\AMod}(C)$ be $\varphi(y):=xy$ for $y\in C$. Then $\varphi(C)\subseteq C$, so Cayley--Hamilton gives $a_1,\ldots,a_n$ such that $\varphi^n+a_1\varphi^{n-1}+\cdots+a_n\equiv0$. Evaluating at $1\in C$ yields
% Source page 3
$x^n+a_1x^{n-1}+\cdots+a_n=0$.
\end{proof}
\setcounter{theorem}{21}\begin{corollary}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item If $x_1,\ldots,x_n\in B$ are integral over $A$, then $A[x_1,\ldots,x_n]$ is a finitely generated $A$-module, by induction on $n$.
\setcounter{enumi}{1}\item Let $\overline A:=\{x\in B\mid x\text{ is integral over }A\}$. Then $\overline A$ is a subring of $B$, called the \emph{integral closure} of $A$ in $B$. Indeed, for $x,y\in\overline A$, $A[x,y]$ is a finitely generated $A$-module by (i), and $A[x\pm y]$ and $A[xy]$ are contained in it.
\setcounter{enumi}{2}\item If $A\subseteq B\subseteq C$ are rings, $B$ is integral over $A$, and $C$ is integral over $B$, then $C$ is integral over $A$.
\setcounter{enumi}{3}\item For rings $A\subseteq B$, one has $\overline{\overline A}=\overline A$.
\end{enumerate}
\end{corollary}
\begin{proof}
For (iii), let $x\in C$. There exist $b_i\in B$ such that $x^n+b_1x^{n-1}+\cdots+b_n=0$. Now $A[b_1,\ldots,b_n]$ is a finitely generated $A$-module, and $A[b_1,\ldots,b_n,x]$ is a finitely generated $A[b_1,\ldots,b_n]$-module. Thus it is a finitely generated $A$-module, and it contains $A[x]$.

For (iv), if $x\in B$ is integral over $\overline A$, apply (iii) to $A\subseteq\overline A\subseteq B$ to conclude that $x$ is integral over $A$.
\end{proof}
These observations culminate in the fact that the integral closure of $A$ in $B$ is integrally closed in $B$, as expected!

\setcounter{definition}{14}\begin{definition}
A ring $R$ is \emph{Jacobson} if, for every prime $\pp$,
\[\pp=\bigcap_{\substack{\mm\supseteq\pp\\\mm\text{ maximal}}}\mm.\]
\end{definition}
\setcounter{example}{8}\begin{example}
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item A field $\kk$ is a Jacobson ring.
\setcounter{enumi}{1}\item $\Z$ is Jacobson: every nonzero prime ideal is maximal, and $(0)=\operatorname{nilradical}(\Z)=\bigcap_{\mm\text{ maximal}}\mm=\bigcap_{\pp\text{ prime}}\pp$.
\setcounter{enumi}{2}\item $\kk[x]$ is Jacobson. It is a PID by the division algorithm. Every nonzero prime is generated by an irreducible polynomial and is therefore maximal. Since $\kk[x]$ is a domain, as in (ii), $(0)=\bigcap_{\mm\text{ maximal}}\mm=\bigcap_{\pp\text{ prime}}\pp$.
\end{enumerate}
\end{example}
The following lemma characterizes Jacobson rings.
\setcounter{theorem}{23}\begin{lemma}
$R$ is Jacobson if and only if, for prime $\pp$ and $0\ne b\in R/\pp$, whenever $(R/\pp)_{(b)}$ is a field, $R/\pp$ is a field.
\end{lemma}
\begin{proof}
Suppose $R$ is Jacobson. Then $S:=R/\widetilde\pp$ is Jacobson for prime $\widetilde\pp$. In $S$,
\[(0)=\bigcap_{\pp\text{ prime}}\pp=\bigcap_{\mm\text{ maximal}}\mm.\tag{*}\]
Suppose $S_{(b)}$ is a field. If $\pp$ is a nonzero prime ideal and $\pp\cap\{1,b,b^2,\ldots\}=\varnothing$, then $(b)^{-1}\pp$ is a nonzero proper ideal of $S_{(b)}$, absurd. Therefore every nonzero prime $\pp$ meets $\{1,b,b^2,\ldots\}$; but (*) gives $b=0$, again absurd. Thus $(0)$ is maximal and $S$ is a field.
% Source page 6
Conversely, let $\qq<R$ be prime and set $I=\bigcap_{\mm\supseteq\qq,\ \mm\text{ maximal}}\mm$. We must show $I=\qq$. Suppose not, and choose $f\in I\setminus\qq$. Set
\[\Sigma=\{\pp\text{ prime in }R\mid\pp\supseteq\qq,\ f\notin\pp\},\]
ordered by inclusion. By Zorn's lemma there is a maximal $\widetilde\pp\in\Sigma$. Clearly $\widetilde\pp$ is not a maximal ideal, as $f$ is in every maximal ideal containing $\qq$. Hence $S:=R/\widetilde\pp$ is not a field, but $S_{(f)}$ is a field, since $\widetilde\pp$ is maximal among the prime ideals disjoint from the powers of $f$. This is a contradiction.
\end{proof}
\setcounter{theorem}{24}\begin{theorem}[Hilbert's Nullstellensatz, Jacobson form]
Let $R$ be a Jacobson ring and $S$ a finitely generated $R$-algebra. Then:
\begin{enumerate}[label=(\roman*)]
\setcounter{enumi}{0}\item $S$ is a Jacobson ring.
\setcounter{enumi}{1}\item If $\nn<S$ is maximal, then $\mm:=\nn\cap R$ is maximal in $R$, and $S/\nn$ is a finite field extension of $R/\mm$.
\end{enumerate}
\end{theorem}
\setcounter{theorem}{25}\begin{lemma}
Let $A\subseteq B$ be domains, with $B$ integral over $A$. Then $B$ is a field if and only if $A$ is a field.
\end{lemma}
\begin{proof}
Let $A$ be a field and $0\ne y\in B$. Choose a monic relation $y^n+a_1y^{n-1}+\cdots+a_n=0$, $a_i\in A$, of least degree. As $B$ is an integral domain, $a_n\ne0$, so $a_n$ is a unit. Hence
\[
y\bigl(-a_n^{-1}(y^{n-1}+a_1y^{n-2}+\cdots+a_{n-1})\bigr)=1.
\]
Thus $y^{-1}=-a_n^{-1}(y^{n-1}+a_1y^{n-2}+\cdots+a_{n-1})$,
% Source page 7
and $B$ is a field. Conversely, if $B$ is a field and $0\ne x\in A$, then $x^{-1}\in B$ is integral over $A$. Thus $x^{-m}+a_1x^{-m+1}+\cdots+a_m=0$, with $a_i\in A$. Therefore
\[
x^{-1}=-(a_1x^{-m+1}+\cdots+a_m)x^{m-1}
=-(a_1+a_2x+\cdots+a_mx^{m-1})\in A.
\]
Hence $A$ is a field.
\end{proof}
\setcounter{theorem}{26}\begin{corollary}
If $\qq<B$ is prime, then $\qq$ is maximal if and only if $\qq^c=\qq\cap A<A$ is maximal.
\end{corollary}
\begin{proof}
$B/\qq$ is integral over $A/\qq^c$. Since $\qq,\qq^c$ are prime, the two quotients are domains.
The preceding lemma now gives the equivalence.
\end{proof}
\begin{proof}[Proof of the Jacobson-form Nullstellensatz]
\emph{Strategy.} To show $S$ is Jacobson, we must show that, for prime $\pp<S$ and $0\ne b\in S/\pp$, if $(S/\pp)_{(b)}$ is a field, then $S/\pp$ is a field. The ring map $R\to S$ induces $R/\pp^c\hookrightarrow S/\pp$. Both quotients are domains. It therefore suffices to show that, for domains $R\hookrightarrow S$, if $b\in S$ and $S_{(b)}$ is a field, then $S$ is a field. We will also show that $R$ is a field and $S$ is a finite extension of $R$, thereby proving both assertions at once. Proceed by induction on the number of generators of the algebra $S$.
% Source page 8
\emph{Base case.} Suppose $S$ is generated by one element $t$. There is a map $R[x]\to S$, sending $x$ to $t$, so $S=R[x]/\mathfrak g$. If $\mathfrak g=0$, then some $b\in R[x]$ makes $R[x]_{(b)}$ a field. Hence $K[x]_{(b)}$ is a field, where $K$ is the field of fractions of $R$. But $K[x]$ is a Jacobson domain, so the lemma, applied to $(0)$, would make $K[x]$ a field, absurd.

Thus $\mathfrak g\ne0$. Choose $p(x)\in\mathfrak g$, $p(x)=p_nx^n+\cdots+p_0$. In $S$ one has $p_nt^n+\cdots+p_0=0$. Consequently, $S_{(p_n)}$ is integral over $R_{(p_n)}$, so $b/p_n$ is integral over $R_{(p_n)}$. Clearing denominators gives $q_mb^m+\cdots+q_0=0$. Since $S$ is a domain, divide by enough powers of $b$ to assume $q_0\ne0$. Then $S_{(b)}$ is integral over $R_{(p_nq_0)}$, since
\[
0=\frac{q_mb^m+\cdots+q_0}{q_0b^m}
=\left(\frac1b\right)^m+\frac{q_1}{q_0}\left(\frac1b\right)^{m-1}+\cdots+\frac{q_m}{q_0}.
\]
Because $S_{(b)}$ is a field, $R_{(p_nq_0)}$ is a field. Since $R$ is a Jacobson domain, $R$ is a field. As $S=R[x]/\mathfrak g$, $S$ is a finite extension of $R$.
% Source page 9
\emph{Inductive step.} If $S$ is an $R$-algebra generated by $r$ elements, let $S'$ be the $R$-subalgebra generated by $r-1$ of them. By induction $S'$ is Jacobson, and so is $S$ by the base case. If $\nn$ is maximal in $S$, then
\[
R/(R\cap\nn)\xhookrightarrow{\ 1\ }S'/(S'\cap\nn)
\xhookrightarrow{\ 2\ }S/\nn,
\]
where the arrows labelled $1$ and $2$ are finite field extensions.
\end{proof}
\setcounter{theorem}{27}\begin{corollary}[Weak Nullstellensatz]
Let $\kk$ be algebraically closed. Every maximal ideal of $\kk[x_1,\ldots,x_n]$ has the form $\mm_P=(x_1-a_1,\ldots,x_n-a_n)$ for $P=(a_1,\ldots,a_n)\in\kk^n$.
\end{corollary}
\begin{proof}
Since $\kk[x_1,\ldots,x_n]/\mm_P\cong\kk$, $\mm_P$ is maximal. If $\nn$ is maximal in $\kk[x_1,\ldots,x_n]$, then $\kk[x_1,\ldots,x_n]/\nn$ is algebraic over $\kk/(\nn\cap\kk)=\kk$. Since $\kk$ is algebraically closed, $\kk[x_1,\ldots,x_n]/\nn=\kk$. Let $a_i=[x_i]$ in this quotient and $P=(a_1,\ldots,a_n)$. Then $\mm_P\subseteq\nn$. Since $\mm_P$ is maximal, $\nn=\mm_P$.
\end{proof}
