\begin{remark}
The discussion of unique ergodicity yields another startling duality between
equidistribution and invariance of measures. It shows that the spaces $X$ and
$\mathcal M(X)$ are intricately connected.
\end{remark}

\setcounter{definition}{10}\begin{definition}[Generic point]
We say that $x\in X$ is \emph{generic for $\mu$} if either of the following
equivalent conditions holds:
\begin{enumerate}[label=(\roman*)]
  \item \emph{Invariant measure in $\mathcal M(X)$:}
  $\displaystyle\frac1n\sum_{j=1}^n\delta_{T^jx}
  \overset{*}{\longrightarrow}\mu$.
  \item \emph{Equidistribution in $X$:}
  $\displaystyle\lim_{n\to\infty}\frac1n\sum_{j=1}^n f(T^jx)
  =\int_Xf\,d\mu$ for every $f\in C(X)$.
\end{enumerate}
\end{definition}

\setcounter{theorem}{23}\begin{proposition}
If $\mu\in\mathcal M^T(X)$ is ergodic, then almost every $x\in X$ is generic.
\end{proposition}

