\subsection*{Definition 4.1}
Let $\mu$ be a Borel probability measure. Then $\mu$ is said to be a \textbf{Gibbs state} (or measure) for $\varphi\in C(X)$ if there exists $C\geq1$ such that, for all $n\geq1$,
\[
\frac{1}{C}\leq
\frac{\mu(T_x^{-n}(B(T^n(x),\xi)))}
{\exp\big(S_n\varphi(x)-nP(T,\varphi)\big)}
\leq C,
\]
where $S_n\varphi(x)=\sum_{j=0}^{n-1}\varphi(T^j(x))$ and $T_x^{-n}$ is the inverse branch of $T^n$ whose image contains $x$.

\subsection*{Theorem 4.2 --- Perron--Frobenius--Ruelle}
Keeping the setting and the notation introduced in mind, the following statements hold:
\begin{enumerate}
    \item There exists a simple eigenvalue $\beta>0$ of $L_\varphi$ and an associated eigenvector $h_\varphi>0$ in $C(X)$.
    \item There exists a unique probability measure $m_\varphi$ on $X$ such that $L_\varphi^*(m_\varphi)=\beta m_\varphi$, and for every $v\in C(X)$,
    \[
    \frac{L_\varphi^n(v)}{\beta^n}
    \longrightarrow
    \frac{h_\varphi\int v\,dm_\varphi}{\int h_\varphi\,dm_\varphi}.
    \]
    \item $\beta=\exp(P(T,\varphi))$.
\end{enumerate}

