\subsection*{Definition 6.3}
    $(J, V, T)$ is a conformal repeller if for $T:V\rightarrow \mathbb{C}$ (a holomorphic function), one has:
    \begin{enumerate}
        \item $\exists$ $C>0$ and $\alpha > 1$ such that $|(T^n)'(z)| \geq C\alpha^n$, $\forall$ $z\in J$, and $n\geq 1$.
        \item $T^{-1}(V) \subset \subset V$, $J = \cap_{n\geq 1}T^{-n}(V)$.
        \item $\forall$ $U$, open, $U\cap J \neq \emptyset$, $\exists$ $n>0$ such that $J \subset T^n(U\cap J)$.
    \end{enumerate}

These objects satisfy some easy-to-observe topological properties summarized
in the following theorem.
\subsection*{Theorem 6.3}
    Given $(J, V, T)$ a conformal repeller, the following statements hold,
    \begin{enumerate}
        \item $T(J) = J$, and $T^{-1}(J) = J$.
        \item $J$ is perfect.
        \item $\exists$ $\beta >0$, such that $\forall$ $x\neq y \in J$, $\exists$ $n$, such that, $|T^n(x) - T^n(y)|\geq \beta$ (i.e. $T$ is expansive on $J$).
        \item $J$ admits a Markov partition $\{J_i\}_{1\leq i\leq k}$.
    \end{enumerate}

\subsection*{Theorem 6.4 — Distortion Lemma}
    Let $m$ be a Gibbs state on $X$, and $\varphi: X\rightarrow \mathbb{R}$ be H\"older-continuous. Assume $P(T,\varphi) =0$. Then there is a constant $E\geq 1$ such that for all $r$ small enough and all $x\in X$ there exists $n = n(x, r)$ such that,
    $$\frac{\log(E) + S_n\varphi(x)}{-\log(E) - \log(|(T^n)'(x)|)} \leq \frac{\log(m(B(x, r)))}{\log(r)} \leq \frac{-\log(E) + S_n\varphi(x)}{\log(E) - \log(|(T^n)'(x)|)}$$

