\setcounter{theorem}{19}\begin{lemma}[Choose a modulus suited to the power]
Using an appropriate modulus for perfect powers often yields elegant solutions:
for cubes, modulo $7$ or $9$; for fourth powers, modulo $5$ or $16$;
for fifth powers, modulo $5$ or $11$. For instance, $x^5\equiv0,\pm1\pmod{11}$, and so on.
\end{lemma}
\paragraph{Applications.}
\begin{enumerate}
\setcounter{enumi}{0}\item Find positive-integer solutions of $x^3+y^3+z^3=2001$.
\setcounter{enumi}{1}\item Find integer solutions of $(x+1)^5+(y-4)^5+1=(x-2)^5+(y+3)^5$.
\end{enumerate}
(1) Let $x\geq y\geq z$. Then $3x^3\geq2001$ and $x^3<2001$, so
$12\geq x\geq9$.
Also $x^3\equiv0,\pm1\pmod9$, but $2001\equiv3\pmod9$.
This forces $x\equiv y\equiv z\equiv1\pmod9$.
The only such number in the interval for $x$ is $10$, so $x=10$.
Then $y^3+z^3=1001$. Arguing similarly gives $10\geq y\geq8$;
only $y=10$ satisfies the congruence, and this puts $z=1$.
Thus the solutions are the permutations of $(10,10,1)$.

\setcounter{theorem}{78}\begin{lemma}[Angle sum of a triangle]\label{lemma:lb1-81}
The sum of all three angles in a triangle is $180^\circ$.
That is, if $ABC$ is a triangle, then $\angle A+\angle B+\angle C=180^\circ$.
\end{lemma}
